// Generated by vibes-espmatter – Panasonic air conditioner / heat pump over its UART service port.
//
// One task owns the UART (9600 baud, 8E1): it polls the unit, parses what it reports and sends
// the changes Matter asked for. Packets end when the line is quiet for 20 ms.
//
// - CN-CNT (protocol of the CZ-TACG1 Wi-Fi adapter): we poll every 5 s and get the whole state;
//   a command is the polled state with the changed bytes.
// - CN-WLAN (protocol of the DNSK-P11 module): a 16-step handshake, then the unit sends reports
//   on its own; we poll every 30 s, answer its pings and send key/value "set" commands.
//
// Protocol details from esphome-panasonic-ac (DomiStyle, MIT license).
#include "espm_pac.h"
#include "espm_config.h"

#include <cstring>
#include <driver/uart.h>
#include <esp_log.h>
#include <esp_timer.h>
#include <freertos/FreeRTOS.h>
#include <freertos/task.h>

static const char *TAG = "mesp_pac";

#define PAC_UART UART_NUM_1
#define RX_BUF_SIZE 160
/** A packet is complete when nothing arrived for this long. */
#define READ_TIMEOUT_MS 20
/** Wait this long after the last change from Matter before sending (merges e.g. mode + setpoint). */
#define DEBOUNCE_MS 300

static void (*s_on_state)(const pac_state_t &state);
static void (*s_listener)(const pac_state_t &state);
static pac_state_t s_state = {false, false, PAC_HEAT, 44, PAC_FAN_AUTO, false, false, PAC_TEMP_UNKNOWN,
                              PAC_TEMP_UNKNOWN};

static portMUX_TYPE s_lock = portMUX_INITIALIZER_UNLOCKED;
static pac_change_t s_pending; // guarded by s_lock
static int64_t s_pending_at;   // guarded by s_lock

static uint8_t s_rx[RX_BUF_SIZE];
static size_t s_rx_len;
static int64_t s_last_read;

static int64_t now_ms()
{
    return esp_timer_get_time() / 1000;
}

static void merge(pac_change_t &into, const pac_change_t &c)
{
    if (c.mask & PAC_SET_POWER) into.power = c.power;
    if (c.mask & PAC_SET_MODE) into.mode = c.mode;
    if (c.mask & PAC_SET_TARGET) into.target_x2 = c.target_x2;
    if (c.mask & PAC_SET_FAN) into.fan = c.fan;
    if (c.mask & PAC_SET_SWING_V) into.swing_v = c.swing_v;
    if (c.mask & PAC_SET_SWING_H) into.swing_h = c.swing_h;
    into.mask |= c.mask;
}

void mesp_pac_request(const pac_change_t &change)
{
    portENTER_CRITICAL(&s_lock);
    merge(s_pending, change);
    s_pending_at = now_ms();
    portEXIT_CRITICAL(&s_lock);
}

static bool has_pending()
{
    portENTER_CRITICAL(&s_lock);
    bool pending = s_pending.mask != 0;
    portEXIT_CRITICAL(&s_lock);
    return pending;
}

/** The queued change, once Matter stopped changing things for DEBOUNCE_MS. */
static bool take_pending(pac_change_t &out)
{
    bool ready = false;
    portENTER_CRITICAL(&s_lock);
    if (s_pending.mask && now_ms() - s_pending_at >= DEBOUNCE_MS) {
        out = s_pending;
        s_pending.mask = 0;
        ready = true;
    }
    portEXIT_CRITICAL(&s_lock);
    return ready;
}

/** Tell Matter – unless it already asked for something newer that a stale report would undo. */
static void publish()
{
    if (has_pending()) return;
    if (s_on_state) s_on_state(s_state);
    if (s_listener) s_listener(s_state);
}

/** Show a sent change right away instead of waiting for the next report. */
static void publish_sent(const pac_change_t &c)
{
    pac_change_t applied = {};
    merge(applied, c);
    if (applied.mask & PAC_SET_POWER) s_state.power = applied.power;
    if (applied.mask & PAC_SET_MODE) s_state.mode = applied.mode;
    if (applied.mask & PAC_SET_TARGET) s_state.target_x2 = applied.target_x2;
    if (applied.mask & PAC_SET_FAN) s_state.fan = applied.fan;
    if (applied.mask & PAC_SET_SWING_V) s_state.swing_v = applied.swing_v;
    if (applied.mask & PAC_SET_SWING_H) s_state.swing_h = applied.swing_h;
    publish();
}

static void write_packet(const uint8_t *data, size_t len)
{
    ESP_LOG_BUFFER_HEX_LEVEL("mesp_pac TX", data, len, ESP_LOG_DEBUG);
    uart_write_bytes(PAC_UART, data, len);
}

static uint8_t sum(const uint8_t *data, size_t len)
{
    uint8_t s = 0;
    for (size_t i = 0; i < len; i++) s += data[i];
    return s;
}

// ---------------------------------------------------------------------------------------------
// CN-CNT (CZ-TACG1)
// ---------------------------------------------------------------------------------------------
#if MESP_PAC_PROTOCOL_CNT
namespace cnt {

constexpr uint8_t CTRL_HEADER = 0xF0;
constexpr uint8_t POLL_HEADER = 0x70;
constexpr int POLL_INTERVAL_MS = 5000;
constexpr int CMD_INTERVAL_MS = 250;
/** No answer to polls for this long: the unit is gone (unplugged, powered down). */
constexpr int OFFLINE_MS = 30000;

static uint8_t s_data[10]; // state bytes of the last poll answer – commands are built from them
static bool s_ready;
static int64_t s_last_sent;
static int64_t s_last_received;

static void send(uint8_t header, const uint8_t *payload, size_t len)
{
    uint8_t packet[2 + sizeof(s_data) + 1];
    packet[0] = header;
    packet[1] = len;
    memcpy(packet + 2, payload, len);
    packet[len + 2] = -sum(packet, len + 2);
    s_last_sent = now_ms();
    write_packet(packet, len + 3);
}

static int16_t temperature(const uint8_t *rx, size_t len, size_t index, size_t fallback)
{
    // 0x80 = not supported by this unit
    if (index < len && rx[index] != 0x80) return (int8_t)rx[index];
    if (fallback < len && rx[fallback] != 0x80) return (int8_t)rx[fallback];
    return PAC_TEMP_UNKNOWN;
}

static void handle(const uint8_t *rx, size_t len)
{
    if (len < 12 || (rx[0] != CTRL_HEADER && rx[0] != POLL_HEADER) || rx[1] != len - 3 || sum(rx, len) != 0) {
        ESP_LOGD(TAG, "Dropping invalid packet (%u bytes)", (unsigned)len);
        return;
    }
    s_last_received = now_ms();
    if (rx[0] != POLL_HEADER) return; // answer to a command: the next poll shows its effect
    memcpy(s_data, rx + 2, sizeof(s_data));
    s_ready = true;

    const uint8_t *d = s_data;
    s_state.valid = true;
    s_state.power = (d[0] & 0x0F) != 0;
    switch (d[0] >> 4) {
    case 0x0: s_state.mode = PAC_AUTO; break;
    case 0x2: s_state.mode = PAC_DRY; break;
    case 0x3: s_state.mode = PAC_COOL; break;
    case 0x4: s_state.mode = PAC_HEAT; break;
    case 0x6: s_state.mode = PAC_FAN; break;
    default: ESP_LOGW(TAG, "Unknown mode 0x%02x", d[0]); break;
    }
    s_state.target_x2 = d[1];
    if (d[3] == 0xA0) s_state.fan = PAC_FAN_AUTO;
    else if (d[3] >= 0x30 && d[3] <= 0x70) s_state.fan = (d[3] >> 4) - 2;
    s_state.swing_v = (d[4] >> 4) == 0x0F;
    s_state.swing_h = (d[4] & 0x0F) == 0x0D;
    s_state.inside_c = temperature(rx, len, 18, 21);
    s_state.outside_c = temperature(rx, len, 19, 22);
    publish();
}

static void send_change(const pac_change_t &c)
{
    uint8_t cmd[sizeof(s_data)];
    memcpy(cmd, s_data, sizeof(cmd));
    if (c.mask & (PAC_SET_POWER | PAC_SET_MODE)) {
        static const uint8_t modes[] = {0x0, 0x3, 0x4, 0x2, 0x6}; // auto, cool, heat, dry, fan
        uint8_t mode = (c.mask & PAC_SET_MODE) ? modes[c.mode] : cmd[0] >> 4;
        bool power = (c.mask & PAC_SET_POWER) ? c.power : (cmd[0] & 0x0F) != 0;
        cmd[0] = (mode << 4) | (power ? 0x04 : 0x00);
    }
    if (c.mask & PAC_SET_TARGET) cmd[1] = c.target_x2;
    if (c.mask & PAC_SET_FAN) {
        cmd[3] = c.fan == PAC_FAN_AUTO ? 0xA0 : (c.fan + 2) << 4;
        cmd[5] &= 0xF0; // leave powerful/quiet, like the remote does
    }
    // A position of 0 means the unit has no such louver: leave it alone.
    if ((c.mask & PAC_SET_SWING_V) && (cmd[4] >> 4)) cmd[4] = (cmd[4] & 0x0F) | (c.swing_v ? 0xF0 : 0x30);
    if ((c.mask & PAC_SET_SWING_H) && (cmd[4] & 0x0F)) cmd[4] = (cmd[4] & 0xF0) | (c.swing_h ? 0x0D : 0x06);
    ESP_LOGI(TAG, "Sending command (changes 0x%02x)", c.mask);
    send(CTRL_HEADER, cmd, sizeof(cmd));
    publish_sent(c);
}

static void tick()
{
    const int64_t now = now_ms();
    pac_change_t change;
    if (s_ready && now - s_last_sent > CMD_INTERVAL_MS && take_pending(change)) {
        send_change(change);
    } else if (now - s_last_sent > POLL_INTERVAL_MS) {
        static const uint8_t poll[10] = {};
        send(POLL_HEADER, poll, sizeof(poll));
    }
    if (s_state.valid && now - s_last_received > OFFLINE_MS) {
        ESP_LOGW(TAG, "The unit stopped answering");
        s_state.valid = false;
        s_ready = false;
        publish();
    }
}

} // namespace cnt
#endif

// ---------------------------------------------------------------------------------------------
// CN-WLAN (DNSK-P11)
// ---------------------------------------------------------------------------------------------
#if !MESP_PAC_PROTOCOL_CNT
namespace wlan {

constexpr uint8_t HEADER = 0x5A;
constexpr int INIT_TIMEOUT_MS = 10000;      // wait after boot before the handshake
constexpr int INIT_END_TIMEOUT_MS = 10000;  // wait for the last handshake packet
constexpr int FIRST_POLL_TIMEOUT_MS = 650;  // wait before the first poll
constexpr int POLL_INTERVAL_MS = 30000;
constexpr int RESPONSE_TIMEOUT_MS = 600;    // resend if the unit didn't answer
constexpr int INIT_FAIL_TIMEOUT_MS = 30000; // handshake failed: start over

static const uint8_t HANDSHAKE_1[] = {0x00, 0x06, 0x00, 0x00};
static const uint8_t HANDSHAKE_2[] = {0x00, 0x09, 0x00, 0x00};
static const uint8_t HANDSHAKE_3[] = {0x00, 0x0C, 0x00, 0x00};
static const uint8_t HANDSHAKE_4[] = {0x00, 0x10, 0x00, 0x01, 0x20};
static const uint8_t HANDSHAKE_5[] = {0x00, 0x11, 0x00, 0x02, 0x00, 0x01};
static const uint8_t HANDSHAKE_6[] = {0x00, 0x12, 0x00, 0x04, 0x01, 0x10, 0x11, 0x12};
static const uint8_t HANDSHAKE_7[] = {0x00, 0x41, 0x00, 0x00};
static const uint8_t HANDSHAKE_8[] = {0x01, 0x4C, 0x00, 0x00};
static const uint8_t HANDSHAKE_9[] = {0x10, 0x00, 0x00, 0x00};
static const uint8_t HANDSHAKE_10[] = {0x10, 0x01, 0x00, 0x05, 0x01, 0x30, 0x01, 0x00, 0x01};
static const uint8_t HANDSHAKE_11[] = {0x00, 0x18, 0x00, 0x00};
static const uint8_t HANDSHAKE_12[] = {0x01, 0x00, 0x00, 0x01, 0x10};
static const uint8_t HANDSHAKE_13[] = {0x10, 0x08, 0x00, 0x09, 0x01, 0x01, 0x30, 0x01, 0x01, 0x02, 0x42, 0x01, 0x42};
static const uint8_t HANDSHAKE_14[] = {0x01, 0x89, 0x00, 0x07, 0x00, 0xB8, 0xB7, 0xF1, 0x9B, 0x4F, 0xA6};
static const uint8_t HANDSHAKE_15[] = {0x00, 0xA0, 0x00, 0x13, 0x00, 0x08, 0x30, 0x32, 0x2E, 0x30, 0x33, 0x2E,
                                       0x30, 0x30, 0x08, 0x30, 0x31, 0x30, 0x31, 0x30, 0x31, 0x30, 0x33};
static const uint8_t HANDSHAKE_16[] = {0x01, 0x00, 0x00, 0x01, 0x11};
static const uint8_t PING[] = {0x01, 0x81, 0x00, 0x03, 0x00, 0x11, 0x12};
static const uint8_t POLL[] = {0x10, 0x09, 0x00, 0x38, 0x01, 0x01, 0x30, 0x01, 0x11, 0x00, 0x80, 0x00, 0x00, 0xB0, 0x00,
                               0x02, 0x31, 0x00, 0x00, 0xA0, 0x00, 0x00, 0xA1, 0x00, 0x00, 0xA5, 0x00, 0x00, 0xA4, 0x00,
                               0x00, 0xB2, 0x00, 0x02, 0x35, 0x00, 0x02, 0x33, 0x00, 0x02, 0x34, 0x00, 0x02, 0x32, 0x00,
                               0x00, 0xBB, 0x00, 0x00, 0xBE, 0x00, 0x02, 0x20, 0x00, 0x02, 0x21, 0x00, 0x00, 0x86, 0x00};
static const uint8_t REPORT_ACK[] = {0x10, 0x8A, 0x00, 0x04, 0x00, 0x01, 0x30, 0x01};

enum state_t { INITIALIZING, HANDSHAKE, FIRST_POLL, HANDSHAKE_ENDING, READY, FAILED };
enum kind_t { NORMAL, RESPONSE, RESEND };

static state_t s_st = INITIALIZING;
static uint8_t s_tx_count; // counter of our packets
static uint8_t s_rx_count; // counter of the unit's packets (used in our responses)
static bool s_waiting;     // for an answer to our last packet
static int64_t s_init_time, s_last_sent;
static uint8_t s_last[96]; // last normal packet, for resends
static size_t s_last_len;

static void send_packet(uint8_t *packet, size_t len, kind_t kind)
{
    packet[0] = HEADER;
    packet[1] = kind == RESPONSE ? s_rx_count : kind == RESEND ? (uint8_t)(s_tx_count - 1) : s_tx_count;
    packet[len - 1] = 0;
    packet[len - 1] = -sum(packet, len);
    if (kind == NORMAL) {
        s_tx_count = s_tx_count == 0xFE ? 0x01 : s_tx_count + 1;
        if (len <= sizeof(s_last)) {
            memcpy(s_last, packet, len);
            s_last_len = len;
        }
    } else if (kind == RESPONSE) {
        s_rx_count = s_rx_count == 0xFE ? 0x01 : s_rx_count + 1;
    }
    if (kind != RESPONSE) s_waiting = true;
    s_last_sent = now_ms();
    write_packet(packet, len);
}

static void send(const uint8_t *cmd, size_t len, kind_t kind = NORMAL)
{
    uint8_t packet[sizeof(POLL) + 3];
    memcpy(packet + 2, cmd, len);
    send_packet(packet, len + 3, kind);
}

static void handle_resend()
{
    if (s_waiting && s_last_len && now_ms() - s_last_sent > RESPONSE_TIMEOUT_MS && !s_rx_len) {
        ESP_LOGD(TAG, "Resending previous packet");
        uint8_t packet[sizeof(s_last)];
        memcpy(packet, s_last, s_last_len);
        send_packet(packet, s_last_len, RESEND);
    }
}

static pac_mode_t mode_of(uint8_t v)
{
    switch (v) {
    case 0x42: return PAC_COOL;
    case 0x43: return PAC_HEAT;
    case 0x44: return PAC_DRY;
    case 0x45: return PAC_FAN;
    default: return PAC_AUTO;
    }
}

static void set_fan(uint8_t v)
{
    if (v == 0x41) s_state.fan = PAC_FAN_AUTO;
    else if (v >= 0x32 && v <= 0x36) s_state.fan = v - 0x31;
}

static void set_swing(uint8_t v)
{
    s_state.swing_v = v == 0x41 || v == 0x43;
    s_state.swing_h = v == 0x41 || v == 0x44;
}

static void handle_handshake(const uint8_t *rx)
{
    const uint8_t a = rx[2], b = rx[3];
    if (a == 0x00 && b == 0x89) send(HANDSHAKE_3, sizeof(HANDSHAKE_3));
    else if (a == 0x00 && b == 0x8C) send(HANDSHAKE_4, sizeof(HANDSHAKE_4));
    else if (a == 0x00 && b == 0x90) send(HANDSHAKE_5, sizeof(HANDSHAKE_5));
    else if (a == 0x00 && b == 0x91) send(HANDSHAKE_6, sizeof(HANDSHAKE_6));
    else if (a == 0x00 && b == 0x92) send(HANDSHAKE_7, sizeof(HANDSHAKE_7));
    else if (a == 0x00 && b == 0xC1) send(HANDSHAKE_8, sizeof(HANDSHAKE_8));
    else if (a == 0x01 && b == 0xCC) send(HANDSHAKE_9, sizeof(HANDSHAKE_9));
    else if (a == 0x10 && b == 0x80) send(HANDSHAKE_10, sizeof(HANDSHAKE_10));
    else if (a == 0x10 && b == 0x81) send(HANDSHAKE_11, sizeof(HANDSHAKE_11));
    else if (a == 0x00 && b == 0x98) send(HANDSHAKE_12, sizeof(HANDSHAKE_12));
    else if (a == 0x01 && b == 0x80) send(HANDSHAKE_13, sizeof(HANDSHAKE_13));
    else if (a == 0x10 && b == 0x88) {
        // answer to handshake 13: nothing to do
    } else if (a == 0x01 && b == 0x09) {
        s_rx_count = rx[1]; // first packet of the unit: its counter
        send(HANDSHAKE_14, sizeof(HANDSHAKE_14), RESPONSE);
    } else if (a == 0x00 && b == 0x20) {
        s_st = FIRST_POLL;
        send(HANDSHAKE_15, sizeof(HANDSHAKE_15), RESPONSE);
    } else {
        ESP_LOGW(TAG, "Unknown packet during the handshake: %02x %02x", a, b);
    }
}

static void handle_packet(const uint8_t *rx, size_t len)
{
    const uint8_t a = rx[2], b = rx[3];
    if (a == 0x01 && b == 0x01) {
        send(PING, sizeof(PING), RESPONSE);
    } else if (a == 0x10 && b == 0x89) { // answer to a poll: the whole state
        if (len != 125) {
            ESP_LOGW(TAG, "Invalid poll answer (%u bytes)", (unsigned)len);
            return;
        }
        s_state.valid = true;
        s_state.power = rx[14] != 0x31;
        s_state.mode = mode_of(rx[18]);
        s_state.target_x2 = rx[22];
        s_state.inside_c = (int8_t)rx[62];
        s_state.outside_c = (int8_t)rx[66];
        set_fan(rx[26]);
        set_swing(rx[30]);
        publish();
    } else if (a == 0x10 && b == 0x0A) { // report: something changed (remote, timer …)
        send(REPORT_ACK, sizeof(REPORT_ACK), RESPONSE);
        if (len < 13) return;
        for (int i = 0; i < rx[10]; i++) {
            size_t at = 12 + i * 4; // key, 0x01, value, ?
            if (at + 2 >= len) break;
            const uint8_t value = rx[at + 2];
            switch (rx[at]) {
            case 0x80:
                if (value == 0x30) s_state.power = true;
                else if (value == 0x31) s_state.power = false;
                break;
            case 0xB0: s_state.mode = mode_of(value); break;
            case 0x31: s_state.target_x2 = value; break;
            case 0xA0: set_fan(value); break;
            case 0xA1: set_swing(value); break;
            default: break;
            }
        }
        publish();
    } else if (a == 0x10 && b == 0x88) {
        // command acknowledged
    } else if (a == 0x01 && b == 0x80) {
        ESP_LOGI(TAG, "Connected to the unit (CN-WLAN)");
        s_st = READY;
    } else {
        ESP_LOGD(TAG, "Unknown packet: %02x %02x", a, b);
    }
}

static void handle(const uint8_t *rx, size_t len)
{
    if (rx[0] == 0x70) return; // defrost status, not used
    if (len < 5) return;
    if (rx[0] == 0x66) { // sync: the unit wants a handshake now
        ESP_LOGI(TAG, "Sync from the unit, starting the handshake");
        s_st = INITIALIZING;
        s_init_time = now_ms() - INIT_TIMEOUT_MS;
        return;
    }
    if (rx[0] != HEADER || sum(rx, len) != 0) {
        ESP_LOGD(TAG, "Dropping invalid packet (%u bytes)", (unsigned)len);
        return;
    }
    if (s_st == READY) {
        // Keep the counters in sync – the unit's own packets carry its counter.
        if (s_waiting ? rx[1] != (uint8_t)(s_tx_count - 1) && rx[1] != 0xFE : rx[1] != s_rx_count) {
            s_rx_count = rx[1];
        }
    }
    s_waiting = false;
    if (s_st == READY || s_st == FIRST_POLL || s_st == HANDSHAKE_ENDING) handle_packet(rx, len);
    else handle_handshake(rx);
}

static uint8_t set_queue[16][2];
static size_t set_count;

static void set(uint8_t key, uint8_t value)
{
    if (set_count < 16) {
        set_queue[set_count][0] = key;
        set_queue[set_count++][1] = value;
    }
}

static void send_change(const pac_change_t &c)
{
    static const uint8_t modes[] = {0x41, 0x42, 0x43, 0x44, 0x45}; // auto, cool, heat, dry, fan
    set_count = 0;
    if (c.mask & PAC_SET_MODE) set(0xB0, modes[c.mode]);
    if (c.mask & PAC_SET_POWER) set(0x80, c.power ? 0x30 : 0x31);
    if (c.mask & PAC_SET_TARGET) set(0x31, c.target_x2);
    if (c.mask & PAC_SET_FAN) {
        set(0xB2, 0x41); // normal (not powerful/quiet)
        set(0xA0, c.fan == PAC_FAN_AUTO ? 0x41 : 0x31 + c.fan);
    }
    if (c.mask & (PAC_SET_SWING_V | PAC_SET_SWING_H)) {
        bool v = (c.mask & PAC_SET_SWING_V) ? c.swing_v : s_state.swing_v;
        bool h = (c.mask & PAC_SET_SWING_H) ? c.swing_h : s_state.swing_h;
        if (v && h) {
            set(0xA1, 0x41);
        } else if (v) {
            set(0xA1, 0x43);
            set(0xA5, 0x43); // left/right: center
        } else if (h) {
            set(0xA1, 0x44);
            set(0xA4, 0x43); // up/down: center
        } else {
            set(0xA1, 0x42);
            set(0xA4, 0x43);
            set(0xA5, 0x43);
            set(0x35, 0x42);
        }
    }
    if (!set_count) return;

    // header, counter, 0x10 0x08 (set), size, 0x01 0x01, 0x30 0x01 count 0x00, then key 0x01 value 0x00 …
    uint8_t packet[12 + 16 * 4] = {};
    const size_t len = 12 + set_count * 4; // the last pair's last byte becomes the checksum
    packet[2] = 0x10;
    packet[3] = 0x08;
    packet[4] = 0x00;
    packet[5] = 4 * set_count - 1 + 6;
    packet[6] = 0x01;
    packet[7] = 0x01;
    packet[8] = 0x30;
    packet[9] = 0x01;
    packet[10] = set_count;
    for (size_t i = 0; i < set_count; i++) {
        packet[12 + i * 4] = set_queue[i][0];
        packet[13 + i * 4] = 0x01;
        packet[14 + i * 4] = set_queue[i][1];
    }
    ESP_LOGI(TAG, "Sending command (changes 0x%02x)", c.mask);
    send_packet(packet, len, NORMAL);
    publish_sent(c);
}

static void tick()
{
    const int64_t now = now_ms();
    if (!s_init_time) s_init_time = now;
    switch (s_st) {
    case INITIALIZING:
        if (now - s_init_time > INIT_TIMEOUT_MS) {
            ESP_LOGI(TAG, "Starting the handshake (CN-WLAN)");
            send(HANDSHAKE_1, sizeof(HANDSHAKE_1)); // no answer to this one
            vTaskDelay(pdMS_TO_TICKS(3));
            send(HANDSHAKE_2, sizeof(HANDSHAKE_2)); // nor this – the resend triggers it
            s_st = HANDSHAKE;
            s_init_time = now;
        }
        break;
    case FIRST_POLL:
        if (now - s_last_sent > FIRST_POLL_TIMEOUT_MS) {
            send(POLL, sizeof(POLL));
            s_st = HANDSHAKE_ENDING;
        }
        break;
    case HANDSHAKE_ENDING:
        if (now - s_last_sent > INIT_END_TIMEOUT_MS) send(HANDSHAKE_16, sizeof(HANDSHAKE_16));
        break;
    case FAILED:
        if (now - s_init_time > INIT_FAIL_TIMEOUT_MS) {
            s_st = INITIALIZING;
            s_init_time = now - INIT_TIMEOUT_MS;
        }
        return;
    default: break;
    }
    if (s_st != READY && s_st != INITIALIZING && now - s_init_time > INIT_FAIL_TIMEOUT_MS) {
        ESP_LOGW(TAG, "Handshake failed – is the unit connected to CN-WLAN? Retrying in %d s",
                 INIT_FAIL_TIMEOUT_MS / 1000);
        s_st = FAILED;
        s_init_time = now;
        s_waiting = false;
        if (s_state.valid) {
            s_state.valid = false;
            publish();
        }
        return;
    }
    handle_resend();
    pac_change_t change;
    if (s_st == READY && !s_waiting && take_pending(change)) {
        send_change(change);
    } else if (s_st == READY && now - s_last_sent > POLL_INTERVAL_MS) {
        send(POLL, sizeof(POLL));
    }
}

} // namespace wlan
#endif

// ---------------------------------------------------------------------------------------------
// Task
// ---------------------------------------------------------------------------------------------

#if MESP_PAC_PROTOCOL_CNT
namespace proto = cnt;
#else
namespace proto = wlan;
#endif

static void pac_task(void *)
{
    uint8_t buf[64];
    while (true) {
        int n = uart_read_bytes(PAC_UART, buf, sizeof(buf), pdMS_TO_TICKS(10));
        const int64_t now = now_ms();
        if (n > 0) {
            if (s_rx_len + n > sizeof(s_rx)) s_rx_len = 0; // garbage: start over
            memcpy(s_rx + s_rx_len, buf, n);
            s_rx_len += n;
            s_last_read = now;
        } else if (s_rx_len && now - s_last_read > READ_TIMEOUT_MS) {
            ESP_LOG_BUFFER_HEX_LEVEL("mesp_pac RX", s_rx, s_rx_len, ESP_LOG_DEBUG);
            proto::handle(s_rx, s_rx_len);
            s_rx_len = 0;
        }
        if (!s_rx_len) proto::tick(); // never talk while the unit is talking
    }
}

void mesp_pac_on_state(void (*cb)(const pac_state_t &state))
{
    s_listener = cb;
}

void mesp_pac_start(void (*on_state)(const pac_state_t &state))
{
    s_on_state = on_state;
    uart_config_t config = {};
    config.baud_rate = 9600;
    config.data_bits = UART_DATA_8_BITS;
    config.parity = UART_PARITY_EVEN;
    config.stop_bits = UART_STOP_BITS_1;
    config.flow_ctrl = UART_HW_FLOWCTRL_DISABLE;
    config.source_clk = UART_SCLK_DEFAULT;
    ESP_ERROR_CHECK(uart_driver_install(PAC_UART, 512, 512, 0, nullptr, 0));
    ESP_ERROR_CHECK(uart_param_config(PAC_UART, &config));
    ESP_ERROR_CHECK(uart_set_pin(PAC_UART, MESP_PAC_TX_GPIO, MESP_PAC_RX_GPIO, UART_PIN_NO_CHANGE, UART_PIN_NO_CHANGE));
    ESP_LOGI(TAG, "Talking to the unit on %s (RX GPIO%d, TX GPIO%d)", MESP_PAC_PROTOCOL_CNT ? "CN-CNT" : "CN-WLAN",
             MESP_PAC_RX_GPIO, MESP_PAC_TX_GPIO);
    xTaskCreate(pac_task, "mesp_pac", 4096, nullptr, 5, nullptr);
}
